  // ============ Merge ============
  public static Logger.LoggerConfig.Builder mergeLoggerConfig(
      Logger.LoggerConfig dst, Logger.LoggerConfig src) {
    Logger.LoggerConfig.Builder builder = dst.toBuilder();
    if (dst.getName().isEmpty()) {
      builder.setName(src.getName());
    }
    if (dst.getFormatValue() == 0) {
      builder.setFormatValue(src.getFormatValue());
    }
    if (dst.getLevelValue() == 0) {
      builder.setLevelValue(src.getLevelValue());
    }
    if (!dst.getDevelopment()) {
      builder.setDevelopment(src.getDevelopment());
    }
    if (!dst.getPrettyPrint()) {
      builder.setPrettyPrint(src.getPrettyPrint());
    }
    if (dst.getOutputPathsList().isEmpty()) {
      builder.addAllOutputPaths(src.getOutputPathsList());
    }
    if (dst.getErrorOutputPathsList().isEmpty()) {
      builder.addAllErrorOutputPaths(src.getErrorOutputPathsList());
    }
    if (!dst.getDisableCaller()) {
      builder.setDisableCaller(src.getDisableCaller());
    }
    if (!dst.getDisableStacktrace()) {
      builder.setDisableStacktrace(src.getDisableStacktrace());
    }
    if (dst.getInitialFieldsMap().isEmpty()) {
      builder.putAllInitialFields(src.getInitialFieldsMap());
    }
    return builder;
  }

  // ============ EnvVar ============
  public static Map<String, String> loggerConfigToEnvVar(Logger.LoggerConfig msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_LOGGER_CONFIG_NAME", msg.getName());
    result.put("PROTO_LOGGER_CONFIG_FORMAT", formatToString(msg.getFormat()));
    result.put("PROTO_LOGGER_CONFIG_LEVEL", levelToString(msg.getLevel()));
    result.put("PROTO_LOGGER_CONFIG_DEVELOPMENT", String.valueOf(msg.getDevelopment()));
    result.put("PROTO_LOGGER_CONFIG_PRETTY_PRINT", String.valueOf(msg.getPrettyPrint()));
    if (!msg.getOutputPathsList().isEmpty()) {
      result.put("PROTO_LOGGER_CONFIG_OUTPUT_PATHS", String.join(",", msg.getOutputPathsList()));
    }
    if (!msg.getErrorOutputPathsList().isEmpty()) {
      result.put(
          "PROTO_LOGGER_CONFIG_ERROR_OUTPUT_PATHS",
          String.join(",", msg.getErrorOutputPathsList()));
    }
    result.put("PROTO_LOGGER_CONFIG_DISABLE_CALLER", String.valueOf(msg.getDisableCaller()));
    result.put(
        "PROTO_LOGGER_CONFIG_DISABLE_STACKTRACE", String.valueOf(msg.getDisableStacktrace()));
    return result;
  }

